/**
 * @brief Switches between CW-primary and tandem CW-actuator motion.
 *
 * @param checked true = CW-primary
 *
 * @note Motion controller refuses CW-primary until the arm is calibrated, in
 *       which case `HandleMotionModeChanged()` sets the button back.
 */
void MainWindow::on_pb_cw_primary_toggled(bool checked) {
    if (checked && !ui_->pb_atc_enable->isChecked()) {
        logger_->Warn(
            "CW-primary requires automatic torque compensation (ATC); "
            "refusing mode change");
        const QSignalBlocker blocker(ui_->pb_cw_primary);  // don't re-emit
        ui_->pb_cw_primary->setChecked(false);
        return;
    }
    emit EnableCwPrimary(checked);
}

/**
 * @brief Toggles whether LIBRA-II's pitch joint is allowed to spin freely.
 *        Useful for simulating loss of power (while retaining control) or
 *        manually moving the arm.
 *
 * @param checked true = free mode
 *
 * @note Asks for confirmation only if a trajectory/move is in progress
 *       (i.e., assumes the arm is balanced if it's idle).
 */
void MainWindow::on_pb_free_mode_toggled(bool checked) {
    if (checked && arm_moving_) {
        const auto reply = QMessageBox::warning(
            this, "Free Mode",
            "The arm is currently in motion!\n"
            "Entering free mode will cancel the active trajectory and release"
            "the pitch joint, which will fall unless the CW is balanced.\n\n"
            "Continue?",
            QMessageBox::Yes | QMessageBox::No, QMessageBox::No);
        if (reply != QMessageBox::Yes) {
            logger_->Info("Free mode cancelled by user");
            const QSignalBlocker blocker(ui_->pb_free_mode);  // don't re-emit
            ui_->pb_free_mode->setChecked(false);
            return;
        }
    }

    emit EnableFreeMode(checked);
}
